    //            mangledString = "\\-=" + mangledString.substring(2);
    //        }

            // 2. Replace each dangerous character with an escape sequence (\| for /, etc.)

            mangledString = mangledString.replaceAll("/", "\\\\|");
            mangledString = mangledString.replaceAll("\\.", "\\\\,");
            mangledString = mangledString.replaceAll(";", "\\\\?");
            mangledString = mangledString.replaceAll("\\$", "\\\\%");
            mangledString = mangledString.replaceAll("<", "\\\\^");
            mangledString = mangledString.replaceAll(">", "\\\\_");
            mangledString = mangledString.replaceAll("\\[", "\\\\{");
            mangledString = mangledString.replaceAll("\\]", "\\\\}");
